export async function registrarPush(idioma: string, pedir = false): Promise<boolean> {
  if (Platform.OS === "web" || JUNTOS_DEMO) return false;
  try {
    const Constants = (await import("expo-constants")).default;
    const projectId = (Constants.expoConfig?.extra as { eas?: { projectId?: string } } | undefined)?.eas?.projectId;
    if (!projectId) return false;
    const N = await import("expo-notifications");
    if (!(pedir ? await pedirPermiso() : (await N.getPermissionsAsync()).granted)) return false;
    const { data: token } = await N.getExpoPushTokenAsync({ projectId });
    await asegurarCuenta();
    await rpc("guardar_token", { p_token: token, p_plataforma: Platform.OS === "ios" ? "ios" : "android", p_idioma: idioma });
    return true;
  } catch {
    return false;
  }
}

