// El límite de 4096 se cuenta en bytes de la carga útil, no en letras.
const bytes = (obj) => new TextEncoder().encode(JSON.stringify(obj)).length;
const uuid = "3f2b8c1e-5d4a-4b7e-9c10-2a6f8e1d7b45";

const duelo = { title: "Te toca jugar", body: "Tu rival ya respondió", data: { partida: uuid }, sound: "default", channelId: "senda_v4" };
console.log("aviso de duelo:", bytes(duelo), "bytes");

const acentos = { ...duelo, body: "Mañana, tu reunión de oración empieza a las 20 h" };
console.log("texto con ñ y tilde:", bytes(acentos), "bytes,", JSON.stringify(acentos).length, "caracteres");

console.log("una «ñ» pesa", new TextEncoder().encode("ñ").length, "bytes; un emoji de manos orando pesa", new TextEncoder().encode("🙏").length);

// ¿Cuántos identificadores de partida entran en el campo data antes de pasar el límite?
let n = 0;
while (bytes({ ...duelo, data: { partidas: Array(n + 1).fill(uuid) } }) <= 4096) n++;
console.log("identificadores de partida que caben en data:", n);
console.log("con", n + 1, "ya pesa", bytes({ ...duelo, data: { partidas: Array(n + 1).fill(uuid) } }), "bytes: supera el límite");
